// CooldownMinutesLT applies the LT predicate on the "cooldown_minutes" field.
func CooldownMinutesLT(v int) predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(sql.FieldLT(FieldCooldownMinutes, v))
}

// CooldownMinutesLTE applies the LTE predicate on the "cooldown_minutes" field.
func CooldownMinutesLTE(v int) predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(sql.FieldLTE(FieldCooldownMinutes, v))
}

// HasUser applies the HasEdge predicate on the "user" edge.
func HasUser() predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UserTable, UserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUserWith applies the HasEdge predicate on the "user" edge with a given conditions (other predicates).
func HasUserWith(preds ...predicate.User) predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(func(s *sql.Selector) {
		step := newUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserSmartSchedulePolicy) predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserSmartSchedulePolicy) predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserSmartSchedulePolicy) predicate.UserSmartSchedulePolicy {
	return predicate.UserSmartSchedulePolicy(sql.NotPredicates(p))
}
